from collections import Counter,defaultdict

task_pay={}
with open('/app/dataset/tasks.csv', newline='', encoding='utf-8') as f:
    for r in csv.DictReader(f):
        task_pay[int(r['task_id'])]=int(float(r['pay_per_completion']))

def parse_tasks(s):
    try:
        v=ast.literal_eval(s)
        return v if isinstance(v,list) else []
    except Exception:
        return [int(x) for x in re.findall(r'\d+', s)]

# frequency of bonus - known task pay combos
freq=Counter()
examples=defaultdict(list)
for r in csv.DictReader(open('/app/dataset/timesheet.csv', newline='', encoding='utf-8')):
    tasks=parse_tasks(r['performed_tasks'])
    known=[t for t in tasks if t in task_pay]
    unknown=[t for t in tasks if t not in task_pay]
    bonus=int(float(r['bonus']))
    known_sum=sum(task_pay[t] for t in known)
    diff=bonus-known_sum
    if unknown or diff!=0:
        key=(tuple(sorted(unknown)), diff, len(tasks), len(known))
        freq[key]+=1
        if len(examples[key])<5:
            examples[key].append((r['id'],r['performed_tasks'],bonus,known_sum))
print('top patterns:')
for key,count in freq.most_common(60):
    print(count,key,examples[key])
