from __future__ import annotations

import calendar
import csv
import json
import re
from collections import defaultdict
from datetime import date, datetime, timedelta
from decimal import Decimal, ROUND_HALF_UP


EMPLOYEES_CSV = "/app/dataset/employees.csv"
TASKS_CSV = "/app/dataset/tasks.csv"
TIMESHEET_CSV = "/app/dataset/timesheet.csv"

# Invalid PESELs in the timesheet are closest to these valid employee records.
EMPLOYEE_ID_FIXES = {
    "15720759071": "75020759171",
    "62020111425": "65020111422",
    "16102016795": "96102016751",
    "84731091580": "87031491580",
    "68011910138": "68011810139",
}


def standard_round(value: float) -> int:
    return int(Decimal(str(value)).quantize(Decimal("1"), rounding=ROUND_HALF_UP))


def correct_date(raw_date: str) -> date:
    try:
        return datetime.strptime(raw_date, "%Y-%m-%d").date()
    except ValueError:
        year, month, day = map(int, raw_date.split("-"))
        last_day = calendar.monthrange(year, month)[1]
        return date(year, month, min(day, last_day))


def parse_tasks(raw_tasks: str) -> tuple[int, ...]:
    return tuple(int(match) for match in re.findall(r"\d+", raw_tasks))


def month_starts(min_date: date, max_date: date, weekday: int) -> list[date]:
    starts: list[date] = []
    cursor = date(min_date.year, min_date.month, 1)
    end = date(max_date.year, max_date.month, 1)
    while cursor <= end:
        start = cursor
        while start.weekday() != weekday:
            start += timedelta(days=1)
        starts.append(start)
        if cursor.month == 12:
            cursor = date(cursor.year + 1, 1, 1)
        else:
            cursor = date(cursor.year, cursor.month + 1, 1)
    return starts


def period_start_for(day: date, starts: list[date]) -> date:
    period_start = starts[0]
    for start in starts:
        if start <= day:
            period_start = start
        else:
            break
    return period_start


def answer() -> dict[str, list[int]]:
    employees = list(csv.DictReader(open(EMPLOYEES_CSV, newline="", encoding="utf-8")))
    employee_rates = {row["PESEL"]: float(row["hourly_rate"]) for row in employees}
    task_pay = {
        int(row["task_id"]): int(float(row["pay_per_completion"]))
        for row in csv.DictReader(open(TASKS_CSV, newline="", encoding="utf-8"))
    }

    raw_rows = list(csv.DictReader(open(TIMESHEET_CSV, newline="", encoding="utf-8")))
    corrected_dates = [correct_date(row["date"]) for row in raw_rows]
    billing_weekday = min(corrected_dates).weekday()
    period_starts = month_starts(min(corrected_dates), max(corrected_dates), billing_weekday)

    seen_rows: set[tuple[object, ...]] = set()
    totals = defaultdict(lambda: {"hours": 0, "bonus": 0})

    for row in raw_rows:
        employee_id = EMPLOYEE_ID_FIXES.get(row["employee_id"], row["employee_id"])
        if employee_id not in employee_rates:
            continue

        work_date = correct_date(row["date"])
        hours_worked = int(row["hours_worked"])
        tasks = parse_tasks(row["performed_tasks"])
        salary_amount = row["salary_amount"]
        bonus_raw = int(float(row["bonus"]))

        dedupe_key = (
            work_date.isoformat(),
            hours_worked,
            tasks,
            employee_id,
            row["facility_id"],
            salary_amount,
            bonus_raw,
        )
        if dedupe_key in seen_rows:
            continue
        seen_rows.add(dedupe_key)

        bonus = sum(task_pay[task_id] for task_id in tasks if task_id in task_pay)
        if not tasks and bonus_raw < 0:
            bonus = abs(bonus_raw)

        totals[(employee_id, period_start_for(work_date, period_starts))]["hours"] += hours_worked
        totals[(employee_id, period_start_for(work_date, period_starts))]["bonus"] += bonus

    result: dict[str, list[int]] = {}
    for employee in employees:
        pesel = employee["PESEL"]
        rate = employee_rates[pesel]
        salaries: list[int] = []
        for start in period_starts:
            bucket = totals[(pesel, start)]
            total_salary = bucket["hours"] * rate + bucket["bonus"]
            salaries.append(standard_round(total_salary))
        result[pesel] = salaries

    return result


if __name__ == "__main__":
    with open("/app/answer.json", "w", encoding="utf-8") as f:
        json.dump(answer(), f, default=list)
